repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('rovers', 30), ('town', 21), ('rovers', 50), ('united', 31), ('rovers', 22), ('united', 42), ('rovers', 40)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.holdings.py:
"""A ledger of fixtures."""


class FixtureLedger:
    def __init__(self, fixtures=()):
        self._fixtures = list(fixtures)

    def fixtures(self):
        """Return the fixtures held (a copy, so callers cannot change the ledger)."""
        return list(self._fixtures)

    def add(self, fixture):
        """Add one fixture to the ledger."""
        self.fixtures().append(fixture)

    def total(self):
        """Return the total goals of the fixtures held."""
        return sum(x.goals for x in self._fixtures)


def describe_fixture(fixture):
    """Return a one-line description of a fixture."""
    return "%s: %s" % (fixture.club, fixture.goals)


def largest_goals(fixtures):
    """Return the largest goals, or None when there are no fixtures."""
    values = [x.goals for x in fixtures]
    return max(values) if values else None
